```python
"""Tiny SQL-flavoured query engine over a list of dict records.

Runs SELECT / WHERE / GROUP BY / HAVING / DISTINCT / ORDER BY / OFFSET /
LIMIT with SQL's three-valued NULL logic.  Only the standard library is
used; grouping and de-duplication are hash based, so 100k rows and tens
of thousands of groups stay fast.
"""

from operator import eq, ne, lt, le, gt, ge, itemgetter


# ==========================================================================
# three-valued logic:  TRUE = True,  FALSE = False,  UNKNOWN = None
# ==========================================================================

_CMP = {"=": eq, "!=": ne, "<": lt, "<=": le, ">": gt, ">=": ge}


def _and3(a, b):
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def _or3(a, b):
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def _not3(a):
    return None if a is None else (not a)


def _in3(value, items):
    if not items:                      # an empty list is always FALSE
        return False
    has_null = False
    for item in items:
        if item is None:
            has_null = True
        elif value is not None and value == item:
            return True
    if value is None or has_null:
        return None
    return False


def _cmp3(op, x, y):
    if x is None or y is None:
        return None
    return _CMP[op](x, y)


# ==========================================================================
# compilation: condition trees -> fast closures (compiled once per query)
# ==========================================================================

def _compile_operand(opnd):
    """["col", name] / ["val", literal] / ["agg", func, arg] -> ctx -> value."""
    kind = opnd[0]
    if kind == "col":
        name = opnd[1]
        return lambda ctx, _n=name: ctx[_n]
    if kind == "val":
        literal = opnd[1]
        return lambda ctx, _l=literal: _l
    key = (opnd[1], opnd[2])                       # ["agg", func, arg]
    return lambda ctx, _k=key: ctx[_k]


def _compile_cond(cond):
    """Condition tree -> ctx -> True / False / None (SQL three-valued)."""
    op = cond[0]
    if op == "and":
        left = _compile_cond(cond[1])
        right = _compile_cond(cond[2])
        def test(ctx, _l=left, _r=right):
            a = _l(ctx)
            if a is False:
                return False
            return _and3(a, _r(ctx))
        return test
    if op == "or":
        left = _compile_cond(cond[1])
        right = _compile_cond(cond[2])
        def test(ctx, _l=left, _r=right):
            a = _l(ctx)
            if a is True:
                return True
            return _or3(a, _r(ctx))
        return test
    if op == "not":
        inner = _compile_cond(cond[1])
        return lambda ctx, _i=inner: _not3(_i(ctx))
    if op == "is_null":
        get = _compile_operand(cond[1])
        return lambda ctx, _g=get: (_g(ctx) is None)
    if op == "in":
        get = _compile_operand(cond[1])
        items = cond[2]
        return lambda ctx, _g=get, _i=items: _in3(_g(ctx), _i)
    if op == "between":
        get = _compile_operand(cond[1])
        lo, hi = cond[2], cond[3]
        def test(ctx, _g=get, _lo=lo, _hi=hi):
            v = _g(ctx)
            a = _cmp3(">=", v, _lo)
            if a is False:
                return False
            return _and3(a, _cmp3("<=", v, _hi))
        return test
    # plain comparison [op, x, y]
    get_x = _compile_operand(cond[1])
    get_y = _compile_operand(cond[2])
    fn = _CMP[cond[0]]
    def test(ctx, _x=get_x, _y=get_y, _fn=fn):
        a = _x(ctx)
        b = _y(ctx)
        if a is None or b is None:
            return None
        return _fn(a, b)
    return test


def _operand_aggs(opnd, out):
    if opnd[0] == "agg":
        out.add((opnd[1], opnd[2]))


def _collect_aggs(cond, out):
    """Gather every (func, arg) aggregate mentioned in a condition."""
    op = cond[0]
    if op == "and" or op == "or":
        _collect_aggs(cond[1], out)
        _collect_aggs(cond[2], out)
    elif op == "not":
        _collect_aggs(cond[1], out)
    elif op in ("is_null", "in", "between"):
        _operand_aggs(cond[1], out)
    else:
        _operand_aggs(cond[1], out)
        _operand_aggs(cond[2], out)


# ==========================================================================
# groups
# ==========================================================================

class _Group:
    """One group: its key, its row count and per-column accumulators.

    Each accumulator slot is [non_null_count, sum, min, max, distinct_set].
    """

    __slots__ = ("key", "count", "accs")

    def __init__(self, key, accs):
        self.key = key
        self.count = 0
        self.accs = accs


def _group_and_project(passing, norm_select, select_cols, select_aggs,
                       having, group_by):
    # ---- group columns: group_by plus every plain select column ----------
    group_cols = list(group_by)
    known = set(group_cols)
    for name in select_cols:
        if name not in known:
            known.add(name)
            group_cols.append(name)
    group_pos = {name: i for i, name in enumerate(group_cols)}

    # ---- aggregates needed by select *and* having ------------------------
    needed = set(select_aggs)
    if having is not None:
        _collect_aggs(having, needed)

    # ---- accumulator plan (one slot per referenced column) ---------------
    req = {}                                    # col -> [sum, minmax, distinct]
    for func, arg in needed:
        if arg == "*":
            continue
        flags = req.get(arg)
        if flags is None:
            flags = [False, False, False]
            req[arg] = flags
        if func in ("sum", "avg"):
            flags[0] = True
        elif func in ("min", "max"):
            flags[1] = True
        elif func == "count_distinct":
            flags[2] = True
    acc_cols = list(req)
    need_sum = [req[c][0] for c in acc_cols]
    need_mm = [req[c][1] for c in acc_cols]
    need_dist = [req[c][2] for c in acc_cols]
    col_index = {c: i for i, c in enumerate(acc_cols)}
    nacc = len(acc_cols)

    def new_group(key):
        accs = [[0, 0, None, None, (set() if need_dist[i] else None)]
                for i in range(nacc)]
        return _Group(key, accs)

    # ---- hashable group key ---------------------------------------------
    if not group_cols:
        def make_key(_row):
            return ()
    elif len(group_cols) == 1:
        only = group_cols[0]
        def make_key(row, _c=only):
            return (row[_c],)
    else:
        make_key = itemgetter(*group_cols)

    groups = {}
    if not group_cols:
        groups[()] = new_group(())       # one group even when nothing passes

    # ---- one pass over the surviving rows --------------------------------
    for row in passing:
        key = make_key(row)
        g = groups.get(key)
        if g is None:
            g = new_group(key)
            groups[key] = g
        g.count += 1
        accs = g.accs
        for i in range(nacc):
            v = row[acc_cols[i]]
            if v is None:
                continue                    # aggregates ignore NULLs
            a = accs[i]
            a[0] += 1
            if need_sum[i]:
                a[1] += v
            if need_mm[i]:
                m = a[2]
                if m is None or v < m:
                    a[2] = v
                m = a[3]
                if m is None or v > m:
                    a[3] = v
            if need_dist[i]:
                a[4].add(v)

    # ---- aggregate evaluators -------------------------------------------
    agg_fns = {}
    for func, arg in needed:
        if arg == "*":
            agg_fns[(func, arg)] = (lambda g: g.count)
            continue
        i = col_index[arg]
        if func == "count":
            agg_fns[(func, arg)] = (lambda g, _i=i: g.accs[_i][0])
        elif func == "count_distinct":
            agg_fns[(func, arg)] = (lambda g, _i=i: len(g.accs[_i][4]))
        elif func == "sum":
            agg_fns[(func, arg)] = (
                lambda g, _i=i: g.accs[_i][1] if g.accs[_i][0] else None)
        elif func == "avg":
            agg_fns[(func, arg)] = (
                lambda g, _i=i: g.accs[_i][1] // g.accs[_i][0]
                if g.accs[_i][0] else None)          # floor division
        elif func == "min":
            agg_fns[(func, arg)] = (
                lambda g, _i=i: g.accs[_i][2] if g.accs[_i][0] else None)
        else:                                        # max
            agg_fns[(func, arg)] = (
                lambda g, _i=i: g.accs[_i][3] if g.accs[_i][0] else None)

    having_test = _compile_cond(having) if having is not None else None

    # ---- HAVING, then SELECT (one output row per surviving group) --------
    out = []
    for g in groups.values():
        values = ({k: agg_fns[k](g) for k in needed} if needed else None)
        if having_test is not None:
            ctx = dict(values)                 # str keys for columns,
            for i, name in enumerate(group_cols):   # tuple keys for aggregates
                ctx[name] = g.key[i]
            if having_test(ctx) is not True:
                continue
        d = {}
        for out_key, kind, a, b in norm_select:
            if kind == "col":
                d[out_key] = g.key[group_pos[a]]
            else:
                d[out_key] = values[(a, b)]
        out.append(d)
    return out


# ==========================================================================
# public entry point
# ==========================================================================

def run_query(rows: list[dict], query: dict) -> list[dict]:
    select = query["select"]
    where = query.get("where")
    having = query.get("having")
    group_by = query.get("group_by") or []
    want_distinct = bool(query.get("distinct"))
    order_by = query.get("order_by")
    offset = query.get("offset") or 0
    limit = query.get("limit")

    # ---- normalise "select": (output key, kind, name/func, arg) ---------
    norm_select = []
    select_cols = []
    select_aggs = []
    for item in select:
        if isinstance(item, str):
            if item == "*":                      # shorthand for ["count", "*"]
                select_aggs.append(("count", "*"))
                norm_select.append(("count(*)", "agg", "count", "*"))
            else:
                select_cols.append(item)
                norm_select.append((item, "col", item, None))
        else:
            func, arg = item[0], item[1]
            select_aggs.append((func, arg))
            norm_select.append(("%s(%s)" % (func, arg), "agg", func, arg))

    has_aggs = bool(select_aggs) or having is not None
    grouped = has_aggs or bool(group_by)

    # ---- 1. WHERE (keep only rows whose condition is TRUE) ---------------
    if where is None:
        passing = list(rows)                     # never touch the input list
    else:
        test = _compile_cond(where)
        passing = [row for row in rows if test(row) is True]

    # ---- 2/3/4. grouping + aggregates + having + select ------------------
    if not grouped:
        out = []
        for row in passing:
            d = {}
            for out_key, _kind, name, _arg in norm_select:
                d[out_key] = row[name]
            out.append(d)
    else:
        out = _group_and_project(passing, norm_select, select_cols,
                                 select_aggs, having, group_by)

    # ---- 5. DISTINCT -----------------------------------------------------
    if want_distinct:
        seen = set()
        unique = []
        for d in out:
            k = tuple(d.values())                # keys are in identical order
            if k not in seen:
                seen.add(k)
                unique.append(d)
        out = unique

    # ---- 6. ORDER BY (stable, applied key by key from last to first) -----
    if order_by:
        for spec in reversed(order_by):
            name = spec[0]
            desc = spec[1] == "desc"
            nulls = spec[2] if len(spec) > 2 else None
            if nulls == "first":
                null_first = True
            elif nulls == "last":
                null_first = False
            else:                                # default: NULL is smallest
                null_first = not desc
            rank_null = 1 if (null_first == desc) else 0
            rank_value = 1 - rank_null
            sign = -1 if desc else 1             # keeps ties in input order

            def keyfn(t, _n=name, _rn=rank_null, _rv=rank_value, _s=sign):
                v = t[1][_n]
                if v is None:
                    return (_rn, None, _s * t[0])
                return (_rv, v, _s * t[0])

            indexed = list(enumerate(out))
            indexed.sort(key=keyfn, reverse=desc)
            out = [d for _i, d in indexed]

    # ---- 7. OFFSET / LIMIT ----------------------------------------------
    if offset:
        out = out[offset:]
    if limit is not None:
        out = out[:limit]
    return out
